"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import type { FormEvent, ReactNode } from "react";
import { ArrowDownLeft, ArrowUpRight, ArrowRight, BookOpen, Building2, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Cloud, Download, ExternalLink, FileCheck2, FileText, FolderOpen, LayoutDashboard, LogOut, Menu, MoreHorizontal, Paperclip, Plus, Printer, ReceiptText, RefreshCw, Search, Settings2, ShieldCheck, Sparkles, TrendingUp, Users, Wallet, X, AlertTriangle, Upload, Mail, Phone, Pencil, Archive, LockKeyhole } from "lucide-react";
import { aggregate, annualTax, CHECKED_DATE, ceidgDeadline, dateLabel, decimal, emptyState, filingDeadline, firstBreach, inPeriod, ksefBreach, money, paidFor, parseMoney, periodRule, SOURCES, today, toCsv, total } from "../lib/domain";
import type { Client, Expense, Sale, State } from "../lib/domain";
import { demoState } from "../lib/demo";
import { clientInput, expenseInput, paymentInput, saleInput, settingsInput, taxInput } from "../lib/validation";

type Tab = "dashboard" | "sales" | "expenses" | "clients" | "tax" | "rules" | "settings";
type Modal = { type: "sale" | "expense" | "client" | "payment" | "saleDetail" | "clientDetail" | "expenseDetail" | "export"; id: string; sale?: Sale; client?: Client; expense?: Expense; correction?: boolean };
const tabs = [{ id: "dashboard", label: "Pulpit", icon: LayoutDashboard }, { id: "sales", label: "Sprzedaż i wpłaty", icon: ArrowDownLeft }, { id: "expenses", label: "Wydatki", icon: ReceiptText }, { id: "clients", label: "Klienci", icon: Users }, { id: "tax", label: "Rozliczenie PIT", icon: FileText }, { id: "rules", label: "Zasady i obowiązki", icon: ShieldCheck }, { id: "settings", label: "Ustawienia", icon: Settings2 }];
const headings: Record<Tab, [string, string]> = { dashboard: ["Twoja działalność, pod kontrolą.", "Wszystko, czego potrzebujesz, żeby spokojnie robić swoje."], sales: ["Sprzedaż i wpłaty", "Ewidencja należności oraz faktycznie otrzymanych pieniędzy."], expenses: ["Wydatki bez zgadywania", "Zapłacone koszty i dowody zakupu w jednym miejscu."], clients: ["Dobre relacje zaczynają się tutaj.", "Twoja mała baza klientów, dostępna na każdym urządzeniu."], tax: ["Przygotuj się do PIT-36", "Roczne zestawienie działalności i przejrzysta prognoza podatku."], rules: ["Wiesz, na czym stoisz.", "Aktualne zasady, ważne progi i źródła urzędowe."], settings: ["Twoja Mała Księga", "Dane sprzedawcy i ustawienia prowadzonej działalności." ] };
const methods = ["Przelew", "Gotówka", "Karta", "Świadczenie niepieniężne", "Inne"];
const uid = () => crypto.randomUUID();
function download(name: string, content: string, type = "text/csv;charset=utf-8") { const url = URL.createObjectURL(new Blob([content], { type })); const a = document.createElement("a"); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
function Field({ label, children, hint, wide = false }: { label: string; children: ReactNode; hint?: string; wide?: boolean }) { return <label className={"field " + (wide ? "wide" : "")}><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function Badge({ children, tone = "green" }: { children: ReactNode; tone?: string }) { return <span className={"badge " + tone}>{children}</span>; }
function Empty({ title, text, action }: { title: string; text: string; action?: ReactNode }) { return <div className="empty"><FolderOpen size={34} strokeWidth={1.3} /><h3>{title}</h3><p>{text}</p>{action}</div>; }
function Metric({ label, value, sub, icon, tone = "green" }: { label: string; value: string; sub: string; icon: ReactNode; tone?: string }) { return <article className="metric"><div className="metric-top"><span>{label}</span><span className={"metric-icon " + tone}>{icon}</span></div><strong>{value}</strong><small>{sub}</small></article>; }

export default function Workspace({ user, signIn, signOut }: { user: { name: string; email: string } | null; signIn: string; signOut: string }) {
  const [data, setData] = useState<State>(() => user ? emptyState() : demoState());
  const [tab, setTab] = useState<Tab>("dashboard"); const [year, setYear] = useState(2026); const [period, setPeriod] = useState(4); const [query, setQuery] = useState(""); const [page, setPage] = useState(0); const [saleView, setSaleView] = useState("sales"); const [statusFilter, setStatusFilter] = useState("all"); const [clientFilter, setClientFilter] = useState(""); const [categoryFilter, setCategoryFilter] = useState("");
  const [modal, setModal] = useState<Modal | null>(null); const [saving, setSaving] = useState(false); const [loaded, setLoaded] = useState(!user); const [sync, setSync] = useState(false); const [error, setError] = useState(""); const [formError, setFormError] = useState(""); const [toast, setToast] = useState(""); const [mobile, setMobile] = useState(false); const [printSale, setPrintSale] = useState<Sale | null>(null); const [printMode, setPrintMode] = useState<"tax" | "sales" | "sale">("tax");
  const [clientSelection, setClientSelection] = useState(""); const [formKind, setFormKind] = useState("sale");
  const savingRef = useRef(false); savingRef.current = saving; const requests = useRef(0); const pending = useRef<{ fingerprint: string; opId: string } | null>(null); const importRef = useRef<HTMLInputElement>(null); const dialogRef = useRef<HTMLDivElement>(null);
  const refresh = useCallback(async (quiet = false) => { if (!user) return; const n = ++requests.current; if (!quiet) setSync(true); try { const r = await fetch("/api/state", { cache: "no-store", credentials: "same-origin" }); const body: any = await r.json(); if (!r.ok) throw new Error(body.error || "Nie udało się odświeżyć danych."); if (n === requests.current) { setData(body); setLoaded(true); setError(""); } } catch (e) { if (n === requests.current) setError((e as Error).message); } finally { if (n === requests.current) setSync(false); } }, [user]);
  useEffect(() => { void refresh(); const focus = () => { if (!document.hidden) void refresh(true); }; window.addEventListener("focus", focus); document.addEventListener("visibilitychange", focus); const timer = setInterval(focus, 30000); return () => { requests.current++; clearInterval(timer); window.removeEventListener("focus", focus); document.removeEventListener("visibilitychange", focus); }; }, [refresh]);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(""), 6000); return () => clearTimeout(t); } }, [toast]);
  useEffect(() => { setPage(0); }, [query, period, year, tab, saleView, statusFilter, clientFilter, categoryFilter]);
  useEffect(() => { if (!modal) return; setFormError(""); setClientSelection(modal.sale?.clientId ?? ""); setFormKind(modal.correction ? "correction" : "sale"); const prev = document.activeElement as HTMLElement | null; const frame = requestAnimationFrame(() => dialogRef.current?.querySelector<HTMLElement>("input,select,button")?.focus()); const key = (e: KeyboardEvent) => { if (e.key === "Escape" && !savingRef.current) setModal(null); if (e.key === "Tab") { const els = [...(dialogRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input,select,textarea,[tabindex="0"]') ?? [])].filter(el => el.offsetParent !== null); const first = els[0], last = els[els.length - 1]; if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); } else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); } } }; document.addEventListener("keydown", key); return () => { cancelAnimationFrame(frame); document.removeEventListener("keydown", key); prev?.focus(); }; }, [modal]);
  const a = aggregate(data, year, period), tax = annualTax(data, year), rule = periodRule(year)!; const periodName = period === 0 ? `Cały rok ${year}` : year === 2025 ? `${String(period).padStart(2, "0")}.${year}` : `${["", "I", "II", "III", "IV"][period]} kwartał ${year}`;
  const breach = data.legalEvents.find(e => e.kind === "dn_breach")?.date ?? firstBreach(data.sales)?.date;
  const ksef = data.legalEvents.find(e => e.kind === "ksef_breach")?.date ?? ksefBreach(data.sales);
  const open = (type: Modal["type"], extras: Partial<Modal> = {}) => { setModal({ type, id: uid(), ...extras }); };
  const go = (id: Tab) => { setTab(id); setQuery(""); setClientFilter(""); setCategoryFilter(""); setStatusFilter("all"); setMobile(false); };
  const notify = (text: string) => setToast(text);
  async function save(action: string, input: any) {
    const validators: Record<string, any> = { client: clientInput, sale: saleInput, payment: paymentInput, expense: expenseInput, settings: settingsInput, tax: taxInput };
    const parsed = validators[action]?.safeParse(input); if (parsed && !parsed.success) throw new Error(parsed.error.issues.map((i: any) => i.message).join(" ")); const payload = parsed?.data ?? input;
    if (!user) {
      setData(old => { const next = structuredClone(old); const timestamp = new Date().toISOString(); if (action === "client") { const c = { ...payload, version: payload.version + 1 }; next.clients = next.clients.filter(c => c.id !== payload.id).concat(c); } if (action === "sale") { const client = next.clients.find(c => c.id === payload.clientId); const s = { ...payload, number: payload.number || `DEMO/${next.sales.length + 1}`, clientName: client?.name ?? "Osoba prywatna", snapshot: JSON.stringify({ seller: next.settings, client: client ?? { name: "Osoba prywatna" } }), createdAt: timestamp }; next.sales.unshift(s); if (payload.initialPayment) next.payments.unshift({ id: uid(), saleId: s.id, date: payload.paymentDate, amount: payload.amount < 0 ? -payload.initialPayment : payload.initialPayment, method: payload.method, note: "Wpłata demonstracyjna", createdAt: timestamp }); } if (action === "payment") next.payments.unshift({ ...payload, createdAt: timestamp }); if (action === "expense") next.expenses.unshift({ ...payload, createdAt: timestamp }); if (action === "settings") next.settings = { ...payload, version: payload.version + 1 }; if (action === "tax") next.tax = next.tax.filter(t => t.year !== payload.year).concat({ ...payload, version: payload.version + 1 }); next.audit.unshift({ id: uid(), action: "Zapis demonstracyjny", details: payload.description ?? payload.name ?? "Ustawienia", createdAt: timestamp }); return next; }); notify("Zmieniono dane przykładowe w tej karcie. Zaloguj się, aby zapisywać w swojej bazie."); return;
    }
    if (!loaded) throw new Error("Poczekaj na wczytanie prywatnej bazy.");
    const fingerprint = JSON.stringify({ action, data: payload }); if (pending.current?.fingerprint !== fingerprint) pending.current = { fingerprint, opId: uid() };
    const r = await fetch("/api/state", { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ opId: pending.current.opId, action, data: payload }) });
    const body: any = await r.json(); if (!r.ok) { if (r.status === 409) { pending.current = null; await refresh(); } throw new Error(body.error || "Nie udało się zapisać danych."); } pending.current = null; await refresh(); notify("Zapisano w Twojej bazie. Dane są dostępne na pozostałych urządzeniach.");
  }
  async function submit(e: FormEvent<HTMLFormElement>, action: string) {
    e.preventDefault(); if (saving) return; setSaving(true); setFormError(""); const form = e.currentTarget; const fd = new FormData(form); const v = (key: string) => String(fd.get(key) ?? ""); const cents = (key: string) => parseMoney(v(key) || "0");
    try {
      let payload: any;
      if (action === "client") payload = { id: modal?.client?.id ?? modal!.id, name: v("name"), nip: v("nip"), email: v("email"), phone: v("phone"), address: v("address"), notes: v("notes"), archived: modal?.client?.archived ?? 0, version: modal?.client?.version ?? 0 };
      if (action === "sale") payload = { id: modal!.id, clientId: v("clientId"), date: v("date"), issueDate: v("issueDate"), dueDate: v("dueDate"), amount: cents("amount"), description: v("description"), category: v("category"), number: v("number"), kind: formKind, parentId: formKind === "correction" ? v("parentId") : "", reason: v("reason"), b2b: fd.has("b2b") ? 1 : 0, ksefEligible: fd.has("ksefEligible") ? 1 : 0, initialPayment: cents("initialPayment"), paymentDate: v("paymentDate"), method: v("method") };
      if (action === "payment") payload = { id: modal!.id, saleId: v("saleId"), date: v("date"), amount: cents("amount"), method: v("method"), note: v("note") };
      if (action === "expense") payload = { id: modal!.id, date: v("date"), paidDate: v("paidDate"), amount: cents("amount"), deductible: cents("deductible"), description: v("description"), category: v("category"), evidence: v("evidence"), notes: v("notes") };
      if (action === "settings") payload = { sellerName: v("sellerName"), sellerAddress: v("sellerAddress"), sellerNip: v("sellerNip"), sellerEmail: v("sellerEmail"), startDate: v("startDate"), eligible60: fd.has("eligible60"), regulated: fd.has("regulated"), specialVat: fd.has("specialVat"), specialCash: fd.has("specialCash"), version: data.settings.version };
      if (action === "tax") payload = { year, otherIncome: cents("otherIncome"), deductions: cents("deductions"), advances: cents("advances"), taxRelief: cents("taxRelief"), version: tax.input.version };
      await save(action, payload);
      const file = fd.get("file"); if (action === "expense" && file instanceof File && file.size) { if (!user) notify("Wydatek dodano w demonstracji. Załączniki zapiszesz po zalogowaniu."); else { const upload = new FormData(); upload.set("file", file); upload.set("expenseId", payload.id); const r = await fetch("/api/files", { method: "POST", body: upload }); const body: any = await r.json(); if (!r.ok) { notify("Wydatek zapisano. Załącznik: " + body.error); } else await refresh(); } }
      setModal(null);
    } catch (e) { setFormError((e as Error).message); } finally { setSaving(false); }
  }
  function exportCsv(kind: string) {
    let rows: unknown[][] = [];
    if (kind === "sales") rows = [["Numer", "Data sprzedaży należnej", "Data wystawienia", "Termin płatności", "Klient", "Opis", "Kategoria", "Kwota PLN", "B2B", "Typ", "Powód korekty"], ...a.sales.map(s => [s.number, s.date, s.issueDate, s.dueDate, s.clientName, s.description, s.category, decimal(s.amount).replace(".", ","), s.b2b ? "Tak" : "Nie", s.kind, s.reason])];
    if (kind === "payments") rows = [["Data otrzymania", "Dokument", "Kwota PLN", "Metoda", "Uwagi"], ...a.payments.map(p => [p.date, data.sales.find(s => s.id === p.saleId)?.number ?? "", decimal(p.amount).replace(".", ","), p.method, p.note])];
    if (kind === "expenses") rows = [["Data dokumentu", "Data zapłaty", "Opis", "Kategoria", "Wydatek PLN", "Koszt podatkowy PLN", "Dowód", "Uwagi"], ...a.expenses.map(e => [e.date, e.paidDate, e.description, e.category, decimal(e.amount).replace(".", ","), decimal(e.deductible).replace(".", ","), e.evidence, e.notes])];
    if (kind === "clients") rows = [["Nazwa", "NIP", "Email", "Telefon", "Adres", "Notatki", "Archiwalny"], ...data.clients.map(c => [c.name, c.nip, c.email, c.phone, c.address, c.notes, c.archived ? "Tak" : "Nie"])];
    download(`mala-ksiega-${kind}-${year}-${period || "rok"}.csv`, toCsv(rows)); notify("Pobrano CSV do otwarcia w Excelu.");
  }
  function backup() { download(`mala-ksiega-kopia-${today()}.json`, JSON.stringify({ format: "mala-ksiega-1", exportedAt: new Date().toISOString(), ...data }, null, 2), "application/json"); }
  async function importBackup(file: File) {
    if (!user) { notify("Zaloguj się, aby importować do prywatnej bazy."); return; }
    if (file.size > 5 * 1024 * 1024) { notify("Kopia przekracza 5 MB."); return; }
    setSaving(true);
    try {
      const b = JSON.parse(await file.text());
      if (b.format !== "mala-ksiega-1" || ![b.clients, b.sales, b.payments, b.expenses].every(Array.isArray)) throw new Error("Nieprawidłowa kopia Małej Księgi.");
      const groups = [["clients", b.clients], ["sales", [...b.sales.filter((s: any) => s.kind === "sale"), ...b.sales.filter((s: any) => s.kind !== "sale")]], ["payments", b.payments], ["expenses", b.expenses]] as const;
      let parts = 0;
      if (b.settings || b.tax || b.legalEvents) {
        await save("import", { format: "mala-ksiega-1", clients: [], sales: [], payments: [], expenses: [], ...(b.settings ? { settings: b.settings } : {}), ...(b.tax ? { tax: b.tax } : {}), ...(b.legalEvents ? { legalEvents: b.legalEvents } : {}) }); parts++;
      }
      for (const [kind, rows] of groups) for (let i = 0; i < rows.length; i += 75) {
        const part = { format: "mala-ksiega-1", clients: [], sales: [], payments: [], expenses: [], [kind]: rows.slice(i, i + 75) };
        await save("import", part); parts++;
      }
      notify(parts ? "Import zakończony. Dane dopisano bez nadpisywania istniejących wpisów. Pliki dowodowe dodaj osobno w szczegółach wydatków." : "Ta kopia nie zawiera wpisów do importu.");
    } catch (e) { notify((e as Error).message + " Możesz ponowić import całej kopii; zapisane identyfikatory nie zostaną powielone."); } finally { setSaving(false); }
  }
  function print(mode: "tax" | "sales" | "sale", sale: Sale | null = null) { setPrintMode(mode); setPrintSale(sale); setTimeout(() => window.print(), 120); }
  const salesFiltered = a.sales.filter(s => (!query || [s.number, s.clientName, s.description, s.category].join(" ").toLowerCase().includes(query.toLowerCase())) && (!clientFilter || s.clientId === clientFilter) && (!categoryFilter || s.category === categoryFilter) && (statusFilter === "all" || (statusFilter === "unpaid" ? s.amount - paidFor(s, data.payments) > 0 : s.amount - paidFor(s, data.payments) <= 0)));
  const paymentsFiltered = a.payments.filter(p => !query || [data.sales.find(s => s.id === p.saleId)?.number, p.note, p.method].join(" ").toLowerCase().includes(query.toLowerCase()));
  const expensesFiltered = a.expenses.filter(e => (!query || [e.description, e.category, e.evidence].join(" ").toLowerCase().includes(query.toLowerCase())) && (!categoryFilter || e.category === categoryFilter));
  const clientsFiltered = data.clients.filter(c => [c.name, c.nip, c.email, c.phone].join(" ").toLowerCase().includes(query.toLowerCase()));
  const selectedLimitDue = period ? a.due : Math.max(0, ...Array.from({ length: rule.periods }, (_, i) => aggregate(data, year, i + 1).due));
  const limitPercent = Math.max(0, selectedLimitDue / rule.limit * 100);
  const months = ["Sty", "Lut", "Mar", "Kwi", "Maj", "Cze", "Lip", "Sie", "Wrz", "Paź", "Lis", "Gru"];
  const monthly = months.map((m, i) => { const prefix = `${year}-${String(i + 1).padStart(2, "0")}`; return { name: m, income: total(data.payments.filter(p => p.date.startsWith(prefix)), p => p.amount), expense: total(data.expenses.filter(e => e.paidDate.startsWith(prefix)), e => e.amount) }; }); const chartMax = Math.max(10000, ...monthly.flatMap(m => [m.income, m.expense]));
  const blocked = !!user && !loaded;
  const dataActions = <><button className="btn ghost" onClick={() => open("export")}><Download size={16} /><span>Eksportuj</span></button><button className="btn primary" disabled={blocked} onClick={() => open(tab === "expenses" ? "expense" : tab === "clients" ? "client" : "sale")}><Plus size={17} />{tab === "expenses" ? "Dodaj wydatek" : tab === "clients" ? "Dodaj klienta" : "Dodaj sprzedaż"}</button></>;

  function SalesTable({ rows, compact = false }: { rows: Sale[]; compact?: boolean }) { return <div className="table-scroll"><table><thead><tr><th>Transakcja / klient</th><th>Data sprzedaży</th><th className="right">Kwota</th><th>Status wpłat</th><th className="right"><span className="sr-only">Akcje</span></th></tr></thead><tbody>{rows.map((s, i) => { const paid = paidFor(s, data.payments); const balance = s.amount - paid; return <tr key={s.id}><td><button className="table-link" onClick={() => open("saleDetail", { sale: s })}><span className={"row-avatar color" + (i % 4)}>{s.clientName.slice(0, 1)}</span><span><strong>{s.description}</strong><small>{s.clientName} <span className="sep">·</span> {s.number}</small></span></button></td><td>{dateLabel(s.date)}</td><td className="right amount">{money(s.amount)}</td><td><Badge tone={s.kind === "correction" ? "gray" : balance <= 0 ? "green" : paid ? "amber" : "gray"}>{s.kind === "correction" ? "Korekta" : balance <= 0 ? "Opłacono" : paid ? "Częściowo" : "Oczekuje"}</Badge></td><td className="right"><button className="icon-btn" aria-label={`Otwórz ${s.number}`} onClick={() => open("saleDetail", { sale: s })}>{compact ? <ChevronRight size={18} /> : <MoreHorizontal size={18} />}</button></td></tr>; })}</tbody></table></div>; }
  function Pager({ count }: { count: number }) { return <div className="pager"><span>{count ? `${page * 10 + 1}–${Math.min(page * 10 + 10, count)} z ${count} wpisów` : "0 wpisów"}</span><div><button className="icon-btn" disabled={page === 0} onClick={() => setPage(p => p - 1)} aria-label="Poprzednia strona"><ChevronLeft size={17} /></button><button className="icon-btn" disabled={(page + 1) * 10 >= count} onClick={() => setPage(p => p + 1)} aria-label="Następna strona"><ChevronRight size={17} /></button></div></div>; }

  return <>
    <div className="app-shell no-print">
      {mobile && <div className="mobile-dimmer" onClick={() => setMobile(false)} />}
      <aside className={"sidebar " + (mobile ? "is-open" : "")}>
        <a className="brand" href="/" aria-label="Mała Księga — strona główna"><span className="brand-mark"><BookOpen size={23} /></span><span>mała<span className="brand-light">księga</span><small>DUŻY SPOKÓJ. MAŁA DZIAŁALNOŚĆ.</small></span></a>
        <div className="workspace-label"><span className="workspace-avatar">{(data.settings.sellerName || user?.name || "P").charAt(0).toUpperCase()}</span><div><strong>{data.settings.sellerName || "Moja działalność"}</strong><small>Działalność nierejestrowana</small></div><ChevronDown size={14} /></div>
        <p className="nav-label">TWOJE FINANSE</p><nav>{tabs.slice(0, 5).map(t => <button key={t.id} className={tab === t.id ? "active" : ""} onClick={() => go(t.id as Tab)}><t.icon size={19} /><span>{t.label}</span>{t.id === "tax" && <span className="nav-tag">PIT-36</span>}</button>)}</nav>
        <p className="nav-label second">WARTO WIEDZIEĆ</p><nav>{tabs.slice(5).map(t => <button key={t.id} className={tab === t.id ? "active" : ""} onClick={() => go(t.id as Tab)}><t.icon size={19} /><span>{t.label}</span></button>)}</nav>
        <div className="sidebar-bottom"><div className="peace-card"><ShieldCheck size={24} /><h4>Mały biznes. Twój spokój.</h4><p>Zasady sprawdzone w źródłach urzędowych.</p><button onClick={() => go("rules")}>Zobacz zasady <ArrowUpRight size={14} /></button></div><div className="sidebar-foot"><span className="tiny-dot" />Prawo: {dateLabel(CHECKED_DATE)}<span>v1.1</span></div></div>
      </aside>
      <div className="main-shell">
        <header className="topbar"><div className="breadcrumbs"><button className="icon-btn mobile-menu" onClick={() => setMobile(!mobile)} aria-label="Otwórz menu"><Menu size={21} /></button><span>Moja działalność</span><ChevronRight size={13} /><strong>{tabs.find(t => t.id === tab)?.label}</strong></div><div className="topbar-right"><span className="sync-state"><Cloud size={16} />{!user ? "Wersja demonstracyjna" : sync ? "Synchronizacja…" : error ? "Brak połączenia" : "Prywatna baza online"}</span>{user ? <><button className={"icon-btn " + (sync ? "rotating" : "")} onClick={() => void refresh()} aria-label="Odśwież dane"><RefreshCw size={16} /></button><span className="user-avatar" title={user.email}>{user.name.charAt(0).toUpperCase()}</span><button className="icon-btn" aria-label="Wyloguj" onClick={async () => { try { const r = await fetch(signOut, { method: "POST" }); if (!r.ok) throw new Error("Nie udało się wylogować."); window.location.assign("/login"); } catch (e) { notify((e as Error).message); } }}><LogOut size={16} /></button></> : <a className="btn small dark" href={signIn} target="_top"><LockKeyhole size={14} /> Zaloguj się</a>}</div></header>
        <main>
          {!user && <div className="demo-banner"><span><Sparkles size={16} /><strong>Poznaj Małą Księgę.</strong> Oglądasz przykładowe dane. Twoja prywatna baza zaczyna się po zalogowaniu.</span><a href={signIn} target="_top">Zacznij prowadzić ewidencję <ArrowRight size={15} /></a></div>}
          {error && <div className="notice danger" role="alert"><AlertTriangle size={19} /><span>{error} Ostatnio wczytane dane mogą być nieaktualne.</span><button onClick={() => void refresh()}>Ponów</button></div>}
          {breach && <div className="notice danger"><AlertTriangle size={20} /><span><strong>Przekroczenie limitu DN: {dateLabel(breach)}.</strong> Działalność staje się gospodarczą od tego dnia. Termin wniosku CEIDG: {dateLabel(ceidgDeadline(breach))}. Kolejny okres nie przywraca uprawnienia. Wpisy od tej daty wymagają osobnego rozliczenia JDG.</span></div>}
          {ksef && <div className="notice amber"><FileText size={19} /><span>Przekroczono pomocniczy próg faktur B2B 10 000 zł: {dateLabel(ksef)}. Sprawdź obowiązek KSeF od faktury przekraczającej i w kolejnych miesiącach. Mała Księga nie wysyła faktur do KSeF.</span></div>}
          <section className="page-heading"><div><div className="eyebrow">{tab === "dashboard" ? "DOBRZE CIĘ WIDZIEĆ" : "MAŁA KSIĘGA"}<span /> {tab === "tax" ? `ROK PODATKOWY ${year}` : periodName.toUpperCase()}</div><h1>{headings[tab][0]}</h1><p>{headings[tab][1]}</p></div><div className="heading-actions">{["dashboard", "sales", "expenses", "clients"].includes(tab) ? dataActions : tab === "tax" ? <button className="btn primary" onClick={() => print("tax")}><Printer size={16} />Drukuj / zapisz PDF</button> : null}</div></section>
          {!["rules", "settings"].includes(tab) && <div className="period-bar"><div className="period-selector"><CalendarDays size={16} /><select aria-label="Rok" value={year} onChange={e => { setYear(Number(e.target.value)); setPeriod(0); }}><option value={2026}>2026</option><option value={2025}>2025</option></select>{tab !== "tax" && tab !== "clients" && <><span className="v-divider" /><select aria-label="Okres" value={period} onChange={e => setPeriod(Number(e.target.value))}><option value={0}>Cały rok</option>{Array.from({ length: rule.periods }, (_, i) => <option key={i} value={i + 1}>{year === 2025 ? months[i] : ["I kwartał", "II kwartał", "III kwartał", "IV kwartał"][i]}</option>)}</select></>}</div><span className="period-note"><span className="tiny-dot" />{user ? loaded ? "Dane przypisane do Twojego konta" : "Wczytywanie danych…" : "Możesz swobodnie przetestować funkcje"}</span></div>}

          {tab === "dashboard" && <>
            {user && loaded && !data.sales.length && <div className="welcome-card"><div><h3>To dobry dzień na pierwszy wpis.</h3><p>Uzupełnij profil, dodaj sprzedaż i zapisuj wpłaty. Ewidencja będzie z Tobą na telefonie i komputerze.</p></div><button className="btn white" onClick={() => go("settings")}>Uzupełnij profil <ArrowRight size={16} /></button></div>}
            <div className="metric-grid"><Metric label="Otrzymane przychody" value={money(a.received)} sub="Faktyczne wpłaty w wybranym okresie" icon={<ArrowDownLeft size={20} />} /><Metric label="Wydatki" value={money(a.spent)} sub="Według daty zapłaty" icon={<ArrowUpRight size={20} />} tone="orange" /><Metric label="Dochód do PIT" value={money(a.profit)} sub="Wpłaty pomniejszone o koszty podatkowe" icon={<Wallet size={20} />} tone="blue" /><Metric label="Pozostało do zapłaty" value={money(a.outstanding)} sub="Saldo wszystkich sprzedaży i wpłat" icon={<CalendarDays size={20} />} tone="purple" /></div>
            <div className="overview-grid"><article className="panel chart-panel"><div className="panel-heading"><div><h2>Jak idzie Twojej działalności?</h2><p>Otrzymane przychody i zapłacone wydatki · {year}</p></div><span className="chart-legend"><span><i />Przychody</span><span><i />Wydatki</span></span></div><div className="chart"><div className="chart-y">{[1, .75, .5, .25, 0].map(n => <span key={n}>{Math.round(chartMax / 100 * n).toLocaleString("pl-PL")}</span>)}</div><div className="chart-plot"><div className="chart-grid">{[0, 1, 2, 3, 4].map(i => <i key={i} />)}</div><div className="bars">{monthly.map((m, i) => <div className={"bar-column " + ((year === 2026 && i === 9) ? "current" : "")} key={m.name} title={`${m.name}: przychody ${money(m.income)}, wydatki ${money(m.expense)}`}><div className="bar-pair"><div className="bar income" style={{ height: `${Math.max(0, m.income / chartMax * 100)}%` }} /><div className="bar expense" style={{ height: `${Math.max(0, m.expense / chartMax * 100)}%` }} /></div><span>{m.name}</span></div>)}</div></div></div><div className="chart-footer"><TrendingUp size={16} /><span>Sprzedaż należna w wybranym okresie: <strong>{money(a.due)}</strong></span><button onClick={() => go("sales")}>Zobacz ewidencję <ArrowRight size={14} /></button></div></article>
            <article className="panel limit-panel"><div className="panel-heading"><div><h2>Twój limit działalności</h2><p>{period ? periodName : "Najwyższy wynik okresu w roku"}</p></div><span className="icon-circle"><ShieldCheck size={18} /></span></div><div className="gauge"><svg viewBox="0 0 200 118" role="img" aria-label={`Wykorzystano ${limitPercent.toFixed(1)} procent limitu`}><path className="gauge-bg" d="M 24 100 A 76 76 0 0 1 176 100" fill="none" pathLength="100" /><path className={"gauge-fill " + (limitPercent >= 90 ? "warning" : "")} d="M 24 100 A 76 76 0 0 1 176 100" fill="none" pathLength="100" strokeDasharray={`${Math.min(100, limitPercent)} 100`} /></svg><div className="gauge-value"><strong>{Math.round(limitPercent)}<span>%</span></strong><small>wykorzystanego limitu</small></div></div><div className="limit-amount"><strong>{money(selectedLimitDue)}</strong><span>z {money(rule.limit)}</span></div><div className="limit-remaining"><span>Pozostaje do limitu</span><strong>{money(Math.max(0, rule.limit - selectedLimitDue))}</strong></div><p className="limit-hint"><CircleHelp size={14} />Limit uwzględnia sprzedaż należną, również jeszcze niezapłaconą.</p></article></div>
            <div className="bottom-grid"><article className="panel transactions-panel"><div className="panel-heading"><div><h2>Ostatnie transakcje <span className="count-chip">{a.sales.length}</span></h2><p>Twoje najnowsze wpisy w ewidencji</p></div><button className="text-button" onClick={() => go("sales")}>Wszystkie <ArrowRight size={15} /></button></div>{a.sales.length ? <SalesTable rows={a.sales.slice(0, 4)} compact /> : <Empty title="Jeszcze bez transakcji" text="Dodaj pierwszy wpis w wybranym okresie." action={<button className="btn ghost" onClick={() => open("sale")}><Plus size={16} />Dodaj sprzedaż</button>} />}</article><article className="tax-reminder"><span className="tax-icon"><FileCheck2 size={24} /></span><span className="eyebrow">BEZ NIESPODZIANEK NA KONIEC ROKU</span><h2>Twój PIT?<br />Już się układa.</h2><p>Przychody, koszty i dochód zebrane w rocznym zestawieniu. Bez przekopywania notatek.</p><div className="deadline"><CalendarDays size={17} /><span>Rozliczenie za {year}<strong>do {dateLabel(filingDeadline(year))}</strong></span></div><button onClick={() => go("tax")}>Przejdź do rozliczenia <ArrowRight size={17} /></button></article></div>
          </>}

          {tab === "sales" && <article className="panel"><div className="ledger-tabs"><button className={saleView === "sales" ? "active" : ""} onClick={() => setSaleView("sales")}>Sprzedaż należna <span>{a.sales.length}</span></button><button className={saleView === "payments" ? "active" : ""} onClick={() => setSaleView("payments")}>Otrzymane wpłaty <span>{a.payments.length}</span></button><span className="ledger-total">Suma: <strong>{money(saleView === "sales" ? a.due : a.received)}</strong></span></div><div className="filter-row"><div className="search"><Search size={17} /><input placeholder="Szukaj klienta, opisu, numeru…" aria-label="Szukaj transakcji" value={query} onChange={e => setQuery(e.target.value)} /></div>{saleView === "sales" && <><select aria-label="Status płatności" value={statusFilter} onChange={e => setStatusFilter(e.target.value)}><option value="all">Każdy status</option><option value="unpaid">Do zapłaty</option><option value="paid">Rozliczone</option></select><select aria-label="Filtr klientów" value={clientFilter} onChange={e => setClientFilter(e.target.value)}><option value="">Wszyscy klienci</option>{data.clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></>}{saleView === "payments" && <button className="btn ghost" disabled={!data.sales.length || blocked} onClick={() => open("payment")}><Plus size={15} />Dodaj wpłatę</button>}</div>{saleView === "sales" ? salesFiltered.length ? <SalesTable rows={salesFiltered.slice(page * 10, page * 10 + 10)} /> : <Empty title="Brak pasujących sprzedaży" text="Zmień filtry albo dodaj nowy wpis." /> : paymentsFiltered.length ? <div className="table-scroll"><table><thead><tr><th>Data wpłaty</th><th>Dokument / klient</th><th>Metoda</th><th>Uwagi</th><th className="right">Kwota do PIT</th></tr></thead><tbody>{paymentsFiltered.slice(page * 10, page * 10 + 10).map(p => { const s = data.sales.find(s => s.id === p.saleId); return <tr key={p.id}><td>{dateLabel(p.date)}</td><td><strong>{s?.number}</strong><small>{s?.clientName}</small></td><td>{p.method}</td><td>{p.note || "—"}</td><td className="right amount">{money(p.amount)}</td></tr>; })}</tbody></table></div> : <Empty title="Jeszcze bez wpłat" text="Sprzedaż i otrzymanie pieniędzy zapisujesz osobno. Możesz też dodać wpłatę przy tworzeniu sprzedaży." />}<Pager count={saleView === "sales" ? salesFiltered.length : paymentsFiltered.length} /></article>}

          {tab === "expenses" && <><div className="two-metrics"><Metric label="Zapłacone wydatki" value={money(a.spent)} sub={periodName} icon={<ReceiptText size={20} />} tone="orange" /><Metric label="Koszty podatkowe" value={money(a.deductible)} sub="Wyłącznie część związana z działalnością i udokumentowana" icon={<FileCheck2 size={20} />} tone="blue" /></div><article className="panel"><div className="filter-row"><div className="search"><Search size={17} /><input aria-label="Szukaj wydatków" placeholder="Szukaj wydatku lub numeru dowodu…" value={query} onChange={e => setQuery(e.target.value)} /></div><select aria-label="Kategoria wydatku" value={categoryFilter} onChange={e => setCategoryFilter(e.target.value)}><option value="">Wszystkie kategorie</option>{[...new Set(data.expenses.map(e => e.category))].map(c => <option key={c}>{c}</option>)}</select></div>{expensesFiltered.length ? <div className="table-scroll"><table><thead><tr><th>Wydatek / dowód</th><th>Data zapłaty</th><th>Kategoria</th><th className="right">Wydatek</th><th className="right">Koszt podatkowy</th><th /></tr></thead><tbody>{expensesFiltered.slice(page * 10, page * 10 + 10).map(e => <tr key={e.id}><td><button className="table-link" onClick={() => open("expenseDetail", { expense: e })}><span className="row-avatar color1"><ReceiptText size={18} /></span><span><strong>{e.description}</strong><small>{e.evidence || "Bez dowodu"} {data.attachments.some(f => f.expenseId === e.id) && <Paperclip size={12} />}</small></span></button></td><td>{dateLabel(e.paidDate)}</td><td><Badge tone="gray">{e.category}</Badge></td><td className="right amount">{money(e.amount)}</td><td className="right amount">{money(e.deductible)}</td><td><button className="icon-btn" aria-label="Szczegóły wydatku" onClick={() => open("expenseDetail", { expense: e })}><ChevronRight size={17} /></button></td></tr>)}</tbody></table></div> : <Empty title="Tu trafią Twoje wydatki" text="Dodaj koszt, podaj datę zapłaty i zachowaj dowód zakupu." action={<button className="btn ghost" onClick={() => open("expense")}><Plus size={15} />Dodaj wydatek</button>} />}<Pager count={expensesFiltered.length} /></article></>}

          {tab === "clients" && <><div className="filter-row client-toolbar"><div className="search"><Search size={17} /><input aria-label="Szukaj klientów" placeholder="Szukaj po nazwie, emailu, NIP…" value={query} onChange={e => setQuery(e.target.value)} /></div><span className="muted">{data.clients.filter(c => !c.archived).length} aktywnych klientów</span></div><div className="client-grid">{clientsFiltered.slice(page * 10, page * 10 + 10).map((c, i) => { const sales = data.sales.filter(s => s.clientId === c.id); const balance = total(sales, s => s.amount - paidFor(s, data.payments)); return <article className={"panel client-card " + (c.archived ? "archived" : "")} key={c.id}><div className="client-card-top"><span className={"client-initial color" + i % 4}>{c.name.split(" ").map(w => w[0]).slice(0, 2).join("")}</span><button className="icon-btn" aria-label={`Szczegóły ${c.name}`} onClick={() => open("clientDetail", { client: c })}><MoreHorizontal size={19} /></button></div><h3>{c.name}</h3><span className="client-type">{c.archived ? "Kontakt archiwalny" : c.nip ? `NIP ${c.nip}` : "Klient indywidualny"}</span><div className="client-contact"><span><Mail size={14} />{c.email || "Brak adresu email"}</span><span><Phone size={14} />{c.phone || "Brak numeru telefonu"}</span></div><div className="client-card-bottom"><span>{sales.length} transakcji<strong>{money(total(sales, s => s.amount))}</strong></span><button className="text-button" onClick={() => open("clientDetail", { client: c })}>{balance > 0 ? <Badge tone="amber">Do zapłaty {money(balance)}</Badge> : <>Szczegóły <ArrowRight size={15} /></>}</button></div></article>; })}</div>{!clientsFiltered.length && <article className="panel"><Empty title="Poznaj swoją bazę klientów" text="Zapisz kontakt raz, a potem przypisuj do niego sprzedaż." action={<button className="btn primary" onClick={() => open("client")}><Plus size={15} />Dodaj klienta</button>} /></article>}<Pager count={clientsFiltered.length} /></>}

          {tab === "tax" && <>
            <div className="notice info"><FileText size={20} /><span>To zestawienie do uzupełnienia PIT-36 i prognoza indywidualnego podatku na skali. Podatek zależy też od innych dochodów i ulg. Formularz składasz w usłudze <a href="https://www.podatki.gov.pl/twoj-e-pit-rozlicz-roczny-pit-online/" target="_blank" rel="noreferrer">Twój e-PIT</a>.</span></div>
            {breach && <div className="notice danger"><AlertTriangle size={20} /><span>W historii jest przekroczenie limitu. Nie traktuj tego zestawienia jako pełnego rozliczenia DN: sprzedaż od {dateLabel(breach)} wymaga rozliczenia jako działalność gospodarcza.</span></div>}
            <div className="tax-grid"><article className="panel annual-summary"><div className="panel-heading"><div><h2>Działalność nierejestrowana</h2><p>Wartości do odpowiedniego wiersza w PIT-36 · {year}</p></div><span className="icon-circle"><BookOpen size={20} /></span></div><dl className="summary-list"><div><dt>Przychód otrzymany</dt><dd>{money(tax.received)}</dd></div><div><dt>Koszty uzyskania przychodu</dt><dd>{money(tax.deductible)}</dd></div><div className="summary-total"><dt>{tax.profit >= 0 ? "Dochód" : "Strata"}</dt><dd>{money(Math.abs(tax.profit))}</dd></div></dl>{tax.loss > 0 && <p className="inline-note">Straty z tej działalności nie odejmujemy od wynagrodzenia z etatu. Rozliczenie strat z poprzednich lat wymaga osobnej analizy tego samego źródła.</p>}<div className="info-strip"><CheckCircle2 size={18} />Z działalności nierejestrowanej nie płacisz miesięcznych zaliczek PIT.</div><div className="deadline-row"><CalendarDays size={19} /><span>Termin rozliczenia i zapłaty<strong>{dateLabel(filingDeadline(year))}</strong></span></div></article><article className="panel tax-estimate"><span className="eyebrow">PROGNOZA NA SKALI</span><h3>Dodatkowy podatek od DN</h3><strong className="tax-big">{money(tax.increment)}</strong><p>Różnica podatku z dochodem DN i bez niego, przed ulgami podatkowymi.</p><div><span>Łączna podstawa po odliczeniach</span><strong>{money(Math.round(tax.base / 100) * 100)}</strong></div><div><span>Łączny podatek po wpisanych ulgach</span><strong>{money(tax.tax)}</strong></div><div><span>{tax.balance >= 0 ? "Przewidywana dopłata" : "Przewidywany zwrot"}</span><strong>{money(Math.abs(tax.balance))}</strong></div><small>Przy danych wpisanych poniżej. Kwota wolna jest wspólna dla dochodów na skali.</small></article></div>
            <article className="panel"><div className="panel-heading"><div><h2>Uzupełnij kontekst podatkowy</h2><p>Wpisuj dane roczne, np. z PIT-11. Zera oznaczają brak innych dochodów lub odliczeń.</p></div></div><form key={`tax-${year}-${tax.input.version}`} className="form-body" onSubmit={e => submit(e, "tax")}><div className="form-grid four"><Field label="Inne dochody na skali (PLN)" hint="Dochód po kosztach, przed wpisanymi niżej odliczeniami."><input name="otherIncome" defaultValue={decimal(tax.input.otherIncome)} inputMode="decimal" required /></Field><Field label="Odliczenia od dochodu (PLN)" hint="Np. uprawnione składki społeczne; nie wpisuj kosztów DN drugi raz."><input name="deductions" defaultValue={decimal(tax.input.deductions)} inputMode="decimal" required /></Field><Field label="Pobrane / zapłacone zaliczki (PLN)" hint="Zaliczki z innych dochodów, np. pobrane przez pracodawcę."><input name="advances" defaultValue={decimal(tax.input.advances)} inputMode="decimal" required /></Field><Field label="Ulgi od podatku (PLN)" hint="Wyłącznie uprawnione odliczenia, bez części podlegającej zwrotowi ponad podatek."><input name="taxRelief" defaultValue={decimal(tax.input.taxRelief)} inputMode="decimal" required /></Field></div>{formError && !modal && <div className="form-error" role="alert">{formError}</div>}<div className="form-actions"><small>Nie uwzględniamy wspólnego rozliczenia, wszystkich ulg ani przenoszenia strat. Dane możesz korygować.</small><button className="btn primary" disabled={saving || blocked}>{saving ? "Zapisywanie…" : "Zapisz i przelicz"}</button></div></form></article>
          </>}

          {tab === "rules" && <>
            <div className="rules-intro"><div><span className="eyebrow">STAN NA {dateLabel(CHECKED_DATE)}</span><h2>Mała działalność.<br />Jasne zasady.</h2><p>Rozdzielamy to, co liczy się do limitu, od tego, co wykazujesz w podatku. Reguły są przypisane do roku i zachowują historię.</p></div><ShieldCheck size={100} strokeWidth={1} /></div><div className="rule-grid"><article className="panel rule-card"><span className="step">01</span><h3>Limit to przychód należny</h3><p>W 2026 r. możesz osiągnąć do <strong>10 813,50 zł na kwartał</strong>. W 2025 r. limit wynosił 3 499,50 zł miesięcznie. Niezapłacona sprzedaż także się liczy. Koszty nie obniżają limitu.</p></article><article className="panel rule-card"><span className="step">02</span><h3>PIT to otrzymane pieniądze</h3><p>Przychody rozpoznajesz przy otrzymaniu pieniędzy lub świadczenia. Koszt rozliczasz po zapłacie i z dowodem zakupu. Częściowe wpłaty mogą należeć do różnych lat.</p></article><article className="panel rule-card"><span className="step">03</span><h3>Jedno rozliczenie roczne</h3><p>Przychód, koszty i dochód albo stratę wpisujesz w PIT-36. Skala to 12% i 32%, z jedną kwotą wolną dla łącznych dochodów na skali. Bez miesięcznych zaliczek z DN.</p></article></div>
            <article className="panel"><div className="panel-heading"><div><h2>Obowiązki zależne od działalności</h2><p>Niższy przychód nie wyłącza wszystkich obowiązków.</p></div></div><div className="rules-details"><details open><summary>Kto może prowadzić działalność nierejestrowaną?</summary><p>Osoba fizyczna, która nie wykonywała działalności gospodarczej w ostatnich 60 miesiącach i mieści się w limicie. Wykluczona jest spółka cywilna oraz działalność wymagająca koncesji, licencji lub wpisu do rejestru działalności regulowanej. Dla cudzoziemców znaczenie ma także podstawa pobytu. Zaznacz swój stan w Ustawieniach.</p></details><details><summary>Co, jeśli przekroczę limit?</summary><p>Działalność staje się gospodarczą od dnia przekroczenia, a na wniosek do CEIDG jest 7 dni. Aplikacja zachowuje wykryte przekroczenie także po korekcie lub zmianie kwartału. Zwrot po przekroczeniu nie daje automatycznego uprawnienia do DN.</p></details><details><summary>VAT i kasa fiskalna</summary><p>Zwolnienie z VAT ma próg 240 000 zł w 2026 r. (proporcjonalny przy rozpoczęciu w trakcie roku), ale wyjątki branżowe mogą wymagać VAT od pierwszej sprzedaży, np. doradztwo, części samochodowe czy internetowa sprzedaż kosmetyków. Nasza ewidencja dotyczy sprzedaży w PLN ze zwolnieniem z VAT. Standardowy próg kasy to 20 000 zł sprzedaży B2C i rolnikom ryczałtowym rocznie, proporcjonalnie do okresu sprzedaży. Niektóre branże wymagają kasy od początku, inne korzystają ze zwolnień, np. przy odpowiednio udokumentowanych przelewach. Sprawdź źródła poniżej. Wydruk z aplikacji nie jest paragonem fiskalnym.</p></details><details><summary>KSeF w 2026 roku</summary><p>Od kwietnia 2026 przejściowe odstępstwo pozwala wystawiać poza KSeF faktury objęte obowiązkiem, jeśli ich suma w miesiącu nie przekracza 10 000 zł brutto. Liczy się data wystawienia, nie sprzedaży ani wpłaty. B2C i ustawowo wyłączone faktury nie wchodzą do tego licznika. Obowiązek od faktury przekraczającej dotyczy także kolejnych miesięcy. Licznik obejmuje tylko wpisy B2B zaznaczone jako faktury objęte obowiązkiem KSeF. Właściwe oznaczenie faktury wymaga sprawdzenia wyłączeń. Aplikacja nie komunikuje się z KSeF. Odstępstwo kończy się 31.12.2026.</p></details><details><summary>Korekty, świadczenia niepieniężne i sytuacje szczególne</summary><p>Korekta zachowuje dokument źródłowy, powód i osobną datę. Wpłaty/zwroty zapisujesz niezależnie. Dla korekt poprzednich lat lub zamkniętych okresów nie przypisujemy automatycznie daty podatkowej — ustal ją według właściwych przepisów. Świadczenie niepieniężne można zapisać jako wpływ o ustalonej wartości. Waluty, czynny VAT, wspólne rozliczenie i ZUS od umów wymagają osobnego narzędzia lub weryfikacji.</p></details><details><summary>Prywatność danych i kopie</summary><p>Publiczna jest aplikacja, a nie Twoje dane. Baza i załączniki wymagają zalogowania i są przypisane do Twojego konta. Do klientów zapisuj tylko potrzebne informacje. Kopia JSON i CSV są dostępne w Eksportuj; zachowuj je bezpiecznie. JSON zawiera metadane załączników; pliki dowodowe pobierasz osobno. Tryb demonstracyjny korzysta z fikcyjnych danych w pamięci karty.</p></details></div></article><article className="panel"><div className="panel-heading"><div><h2>Sprawdź u źródła</h2><p>Materiały Ministerstwa Finansów i tekst rozporządzenia</p></div><Badge>Zweryfikowano {dateLabel(CHECKED_DATE)}</Badge></div><div className="sources">{SOURCES.map(s => <a href={s.url} target="_blank" rel="noreferrer" key={s.url}><FileText size={18} /><span>{s.title}<small>{new URL(s.url).host}</small></span><ExternalLink size={15} /></a>)}</div></article>
          </>}

          {tab === "settings" && <><article className="panel"><div className="panel-heading"><div><h2>Profil sprzedawcy</h2><p>Dane trafiają do nowych dokumentów. Historia dokumentów zachowuje wcześniejsze dane.</p></div><Building2 size={23} /></div><form key={data.settings.version} className="form-body" onSubmit={e => submit(e, "settings")}><div className="form-grid"><Field label="Imię i nazwisko / nazwa"><input name="sellerName" defaultValue={data.settings.sellerName} maxLength={160} /></Field><Field label="NIP (jeśli posiadasz)" hint="Nie zbieramy numeru PESEL."><input name="sellerNip" defaultValue={data.settings.sellerNip} maxLength={20} /></Field><Field label="Adres"><input name="sellerAddress" defaultValue={data.settings.sellerAddress} maxLength={400} /></Field><Field label="Email"><input name="sellerEmail" type="email" defaultValue={data.settings.sellerEmail} maxLength={200} /></Field><Field label="Data rozpoczęcia działalności"><input type="date" name="startDate" defaultValue={data.settings.startDate} min="2025-01-01" max="2026-12-31" /></Field></div><h3 className="form-subheading">Sprawdź swój zakres obowiązków</h3><div className="checklist"><label><input name="eligible60" type="checkbox" defaultChecked={data.settings.eligible60} /><span>Potwierdzam niewykonywanie działalności gospodarczej przez ostatnie 60 miesięcy.</span></label><label><input name="regulated" type="checkbox" defaultChecked={data.settings.regulated} /><span>Moja działalność wymaga koncesji, licencji, wpisu do rejestru lub jest spółką cywilną.</span></label><label><input name="specialVat" type="checkbox" defaultChecked={data.settings.specialVat} /><span>Sprzedaję towary lub usługi wyłączone ze zwolnienia z VAT albo jestem czynnym podatnikiem VAT.</span></label><label><input name="specialCash" type="checkbox" defaultChecked={data.settings.specialCash} /><span>Moja branża może wymagać kasy fiskalnej od pierwszej sprzedaży.</span></label></div>{!data.settings.eligible60 && <p className="inline-note">Sprawdź prawo do DN przed rozpoczęciem. Sam brak wpisu do CEIDG nie potwierdza warunku 60 miesięcy.</p>}{(data.settings.regulated || data.settings.specialVat || data.settings.specialCash) && <div className="notice amber"><AlertTriangle size={20} /><span>Zaznaczono szczególne obowiązki. Ten zakres może wykraczać poza ewidencję DN ze zwolnieniem z VAT. Sprawdź Zasady i obowiązki.</span></div>}{formError && !modal && <div className="form-error">{formError}</div>}<div className="form-actions"><span className="muted"><LockKeyhole size={14} />Dane prywatne, dostępne po zalogowaniu</span><button className="btn primary" disabled={saving || blocked}>{saving ? "Zapisywanie…" : "Zapisz ustawienia"}</button></div></form></article><article className="panel"><div className="panel-heading"><div><h2>Historia zmian</h2><p>Ostatnie 100 zdarzeń w Twojej ewidencji</p></div><Cloud size={21} /></div><div className="audit-list">{data.audit.slice(0, 15).map(e => <div key={e.id}><span className="audit-dot" /><span><strong>{e.action}</strong><small>{e.details}</small></span><time>{dateLabel(e.createdAt.slice(0, 10))}</time></div>)}{!data.audit.length && <p className="muted">Historia pojawi się po pierwszym zapisie.</p>}</div></article></>}

          <footer className="main-footer"><span><BookOpen size={14} />małaksięga <span className="sep">·</span> Mniej papierów. Więcej swojego.</span><button onClick={() => go("rules")}>Zasady i źródła <ExternalLink size={12} /></button></footer>
        </main>
      </div>
    </div>
    {toast && <div role="status" className="toast no-print"><CheckCircle2 size={19} /><span>{toast}</span><button onClick={() => setToast("")} aria-label="Zamknij komunikat"><X size={15} /></button></div>}
    <input ref={importRef} type="file" accept="application/json,.json" className="sr-only" aria-label="Import kopii JSON" onChange={e => { if (e.target.files?.[0]) void importBackup(e.target.files[0]); e.target.value = ""; }} />

    {modal && <div className="modal-backdrop no-print" onClick={e => { if (e.target === e.currentTarget && !saving) setModal(null); }}><div className={"modal " + (["export", "clientDetail", "expenseDetail", "saleDetail"].includes(modal.type) ? "detail-modal" : "")} ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span className="eyebrow">TWOJA EWIDENCJA</span><h2 id="modal-title">{({ sale: modal.correction ? "Korekta sprzedaży" : "Dodaj sprzedaż", expense: "Dodaj wydatek", client: modal.client ? "Edytuj klienta" : "Nowy klient", payment: "Wpłata lub zwrot", saleDetail: modal.sale?.number ?? "Sprzedaż", clientDetail: modal.client?.name ?? "Klient", expenseDetail: "Szczegóły wydatku", export: "Twoje dane. Twój wybór." })[modal.type]}</h2></div><button className="icon-btn" disabled={saving} onClick={() => setModal(null)} aria-label="Zamknij okno"><X size={20} /></button></header>
      {modal.type === "sale" && <form onSubmit={e => submit(e, "sale")}><div className="form-grid"><Field label="Rodzaj wpisu"><select value={formKind} onChange={e => setFormKind(e.target.value)}><option value="sale">Sprzedaż</option><option value="correction">Korekta sprzedaży</option></select></Field><Field label="Klient"><select name="clientId" value={clientSelection} onChange={e => setClientSelection(e.target.value)}><option value="">Osoba prywatna — bez kontaktu</option>{data.clients.filter(c => !c.archived).map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></Field>{formKind === "correction" && <><Field label="Dokument źródłowy" wide><select name="parentId" defaultValue={modal.sale?.id ?? ""} required><option value="">Wybierz dokument</option>{data.sales.filter(s => s.kind === "sale").map(s => <option key={s.id} value={s.id}>{s.number} — {s.clientName} — {money(s.amount)}</option>)}</select></Field><Field label="Powód korekty" wide><input name="reason" required maxLength={1000} placeholder="Np. zwrot towaru lub korekta błędnego wpisu" /></Field><div className="notice amber wide"><AlertTriangle size={18} /><span>Wpisz różnicę, np. −100,00 dla obniżenia o 100 zł. Zwrot pieniędzy zapisz osobno. Datę korekty wcześniejszego okresu ustal zgodnie z przepisami.</span></div></>}<Field label="Przedmiot sprzedaży" wide><textarea name="description" required maxLength={1500} rows={2} defaultValue={modal.correction ? modal.sale?.description : ""} placeholder="Co sprzedajesz lub jaką usługę wykonujesz?" /></Field><Field label="Kwota brutto (PLN)"><input name="amount" inputMode="decimal" required placeholder={formKind === "correction" ? "−100,00" : "0,00"} /></Field><Field label="Kategoria"><input name="category" list="sale-categories" defaultValue={modal.sale?.category ?? "Usługi"} required maxLength={80} /><datalist id="sale-categories">{["Usługi", "Towary", "Rękodzieło", "Korepetycje", "Inne"].map(v => <option key={v}>{v}</option>)}</datalist></Field><Field label={formKind === "correction" ? "Data ujęcia korekty w limicie" : "Data sprzedaży należnej"} hint="Ta data przypisuje przychód do limitu DN."><input type="date" name="date" defaultValue={today()} min="2025-01-01" max="2026-12-31" required /></Field><Field label="Data wystawienia dokumentu"><input type="date" name="issueDate" defaultValue={today()} min="2025-01-01" max="2026-12-31" required /></Field><Field label="Termin płatności"><input type="date" name="dueDate" defaultValue={today()} min="2025-01-01" max="2026-12-31" required /></Field><Field label="Numer (opcjonalnie)" hint="Puste: automatyczny numer ewidencji E/rok/n."><input name="number" maxLength={80} placeholder="Automatycznie" /></Field><label className="check-row wide"><input type="checkbox" name="b2b" defaultChecked={!!modal.sale?.b2b} /><span>Sprzedaż B2B / faktura dla firmy — wymaga klienta z NIP.</span></label><label className="check-row wide"><input type="checkbox" name="ksefEligible" defaultChecked={!!modal.sale?.ksefEligible} /><span>Uwzględnij w limicie KSeF: faktura B2B objęta obowiązkiem, bez ustawowych wyłączeń. Nie zaznaczaj dla samego wpisu ewidencji, B2C ani faktury z kasy objętej wyłączeniem.</span></label><div className="form-separator wide">{formKind === "correction" ? "ZWROT PIENIĘDZY (OPCJONALNIE)" : "CZY OTRZYMANO JUŻ PIENIĄDZE?"}</div><Field label={formKind === "correction" ? "Zwrócona kwota (PLN)" : "Otrzymana kwota (PLN)"} hint="0 = dodaj płatność później. Możliwa część kwoty."><input name="initialPayment" inputMode="decimal" defaultValue="0,00" /></Field><Field label="Data wpływu / zwrotu — do PIT"><input type="date" name="paymentDate" defaultValue={today()} min="2025-01-01" max="2026-12-31" /></Field><Field label="Sposób płatności"><select name="method">{methods.map(v => <option key={v}>{v}</option>)}</select></Field></div>{formError && <div className="form-error" role="alert">{formError}</div>}<div className="modal-footer"><span>Wpis zachowamy w historii. Błędy poprawisz korektą.</span><button className="btn primary" disabled={saving || blocked}>{saving ? "Zapisywanie…" : "Zapisz sprzedaż"}</button></div></form>}
      {modal.type === "payment" && <form onSubmit={e => submit(e, "payment")}><div className="form-grid"><Field label="Dokument sprzedaży" wide><select name="saleId" defaultValue={modal.sale?.id ?? ""} required><option value="">Wybierz sprzedaż</option>{data.sales.map(s => <option key={s.id} value={s.id}>{s.number} — {s.clientName} ({money(s.amount - paidFor(s, data.payments))} salda)</option>)}</select></Field><Field label="Kwota (PLN)" hint="Dodatnia = wpływ, ujemna = zwrot pieniędzy."><input name="amount" inputMode="decimal" required defaultValue={modal.sale ? decimal(modal.sale.amount - paidFor(modal.sale, data.payments)) : ""} /></Field><Field label="Data otrzymania / zwrotu"><input name="date" type="date" defaultValue={today()} min="2025-01-01" max="2026-12-31" required /></Field><Field label="Sposób"><select name="method">{methods.map(v => <option key={v}>{v}</option>)}</select></Field><Field label="Notatka"><input name="note" placeholder="Np. druga rata lub zwrot" maxLength={500} /></Field><p className="inline-note wide">Zapisz rzeczywisty przepływ pieniędzy. Zwrot wpłaty nie koryguje automatycznie sprzedaży należnej. Zaliczki i zwroty między latami wymagają prawidłowego przypisania podatkowego.</p></div>{formError && <div className="form-error">{formError}</div>}<div className="modal-footer"><span>Płatność trafi do PIT w roku wskazanej daty.</span><button className="btn primary" disabled={saving || blocked}>{saving ? "Zapisywanie…" : "Zapisz wpłatę"}</button></div></form>}
      {modal.type === "expense" && <form onSubmit={e => submit(e, "expense")}><div className="form-grid"><Field label="Opis wydatku" wide><input name="description" required maxLength={1500} placeholder="Np. materiały do zamówień" /></Field><Field label="Kwota wydatku (PLN)" hint="Przy zwrocie kosztu wpisz wartość ujemną."><input name="amount" required inputMode="decimal" placeholder="0,00" /></Field><Field label="Część podatkowa (PLN)" hint="Wpisz tylko udokumentowaną część związaną z działalnością. 0 = poza kosztami PIT."><input name="deductible" required inputMode="decimal" placeholder="0,00" /></Field><Field label="Data dokumentu"><input type="date" name="date" defaultValue={today()} min="2025-01-01" max="2026-12-31" required /></Field><Field label="Data faktycznej zapłaty" hint="Koszt jest ujmowany według tej daty."><input type="date" name="paidDate" defaultValue={today()} min="2025-01-01" max="2026-12-31" required /></Field><Field label="Kategoria"><select name="category">{["Materiały", "Towary", "Sprzęt", "Oprogramowanie", "Transport", "Usługi", "Inne"].map(v => <option key={v}>{v}</option>)}</select></Field><Field label="Numer / opis dowodu zakupu"><input name="evidence" maxLength={200} placeholder="Np. FV/2026/123" /></Field><Field label="Dowód zakupu — PDF, JPG, PNG" hint="Opcjonalnie, do 5 MB. Dostępny tylko dla Twojego konta." wide><input name="file" type="file" accept="application/pdf,image/jpeg,image/png" /></Field><Field label="Notatka / powód korekty" wide><textarea name="notes" rows={2} maxLength={2000} /></Field></div>{formError && <div className="form-error">{formError}</div>}<div className="modal-footer"><span>Zachowaj dowód potwierdzający wydatek.</span><button className="btn primary" disabled={saving || blocked}>{saving ? "Zapisywanie…" : "Zapisz wydatek"}</button></div></form>}
      {modal.type === "client" && <form onSubmit={e => submit(e, "client")}><div className="form-grid"><Field label="Imię i nazwisko / nazwa" wide><input name="name" required maxLength={160} defaultValue={modal.client?.name} placeholder="Jak nazywa się Twój klient?" /></Field><Field label="Email"><input name="email" type="email" maxLength={200} defaultValue={modal.client?.email} /></Field><Field label="Telefon"><input name="phone" type="tel" maxLength={40} defaultValue={modal.client?.phone} /></Field><Field label="NIP (opcjonalnie)"><input name="nip" maxLength={20} defaultValue={modal.client?.nip} placeholder="Dla klienta firmowego" /></Field><Field label="Adres"><input name="address" maxLength={400} defaultValue={modal.client?.address} /></Field><Field label="Prywatna notatka" wide><textarea name="notes" rows={3} maxLength={2000} defaultValue={modal.client?.notes} /></Field></div>{formError && <div className="form-error">{formError}</div>}<div className="modal-footer"><span>Zapisuj wyłącznie potrzebne dane kontaktowe.</span><button className="btn primary" disabled={saving || blocked}>{saving ? "Zapisywanie…" : "Zapisz klienta"}</button></div></form>}
      {modal.type === "saleDetail" && modal.sale && <div className="detail-body"><div className="detail-hero"><span>{modal.sale.kind === "correction" ? "Korekta" : "Sprzedaż należna"}</span><strong>{money(modal.sale.amount)}</strong><h3>{modal.sale.description}</h3><p>{modal.sale.clientName}</p></div><dl className="summary-list"><div><dt>Data sprzedaży</dt><dd>{dateLabel(modal.sale.date)}</dd></div><div><dt>Data wystawienia</dt><dd>{dateLabel(modal.sale.issueDate)}</dd></div><div><dt>Termin płatności</dt><dd>{dateLabel(modal.sale.dueDate)}</dd></div><div><dt>Otrzymano / zwrócono</dt><dd>{money(paidFor(modal.sale, data.payments))}</dd></div><div><dt>Saldo</dt><dd>{money(modal.sale.amount - paidFor(modal.sale, data.payments))}</dd></div>{modal.sale.parentId && <div><dt>Dokument źródłowy</dt><dd>{data.sales.find(s => s.id === modal.sale?.parentId)?.number}</dd></div>}</dl>{modal.sale.reason && <p className="inline-note">Powód: {modal.sale.reason}</p>}<h4>Historia płatności</h4><div className="payment-history">{data.payments.filter(p => p.saleId === modal.sale?.id).map(p => <div key={p.id}><span>{dateLabel(p.date)} · {p.method}<small>{p.note}</small></span><strong>{money(p.amount)}</strong></div>)}{!data.payments.some(p => p.saleId === modal.sale?.id) && <p className="muted">Brak wpłat do tego dokumentu.</p>}</div><div className="detail-actions"><button className="btn primary" onClick={() => open("payment", { sale: modal.sale })}><Plus size={15} />Wpłata / zwrot</button><button className="btn ghost" onClick={() => print("sale", modal.sale)}><Printer size={15} />Potwierdzenie wpisu</button>{modal.sale.kind === "sale" && <button className="btn ghost" onClick={() => open("sale", { sale: modal.sale, correction: true })}><Pencil size={15} />Korekta</button>}</div></div>}
      {modal.type === "clientDetail" && modal.client && <div className="detail-body"><div className="contact-details"><p><Mail size={17} />{modal.client.email || "Nie podano emailu"}</p><p><Phone size={17} />{modal.client.phone || "Nie podano telefonu"}</p><p><Building2 size={17} />{modal.client.address || "Nie podano adresu"}</p>{modal.client.nip && <p>NIP {modal.client.nip}</p>}{modal.client.notes && <p className="inline-note">{modal.client.notes}</p>}</div><h4>Historia sprzedaży</h4><div className="payment-history">{data.sales.filter(s => s.clientId === modal.client?.id).map(s => <button key={s.id} onClick={() => open("saleDetail", { sale: s })}><span>{s.number}<small>{s.description}</small></span><strong>{money(s.amount)}</strong><ChevronRight size={15} /></button>)}</div><div className="detail-actions"><button className="btn primary" onClick={() => open("client", { client: modal.client })}><Pencil size={15} />Edytuj kontakt</button><button className="btn ghost" disabled={saving} onClick={async () => { setSaving(true); try { await save("client", { ...modal.client!, archived: modal.client?.archived ? 0 : 1 }); setModal(null); } catch (e) { setFormError((e as Error).message); } finally { setSaving(false); } }}><Archive size={15} />{modal.client.archived ? "Przywróć" : "Archiwizuj"}</button></div>{formError && <p className="form-error">{formError}</p>}<p className="inline-note">Archiwizacja kontaktu zachowuje sprzedaż, wpłaty i dane na historycznych dokumentach.</p></div>}
      {modal.type === "expenseDetail" && modal.expense && <div className="detail-body"><div className="detail-hero"><span>{modal.expense.category}</span><strong>{money(modal.expense.amount)}</strong><h3>{modal.expense.description}</h3></div><dl className="summary-list"><div><dt>Data zapłaty</dt><dd>{dateLabel(modal.expense.paidDate)}</dd></div><div><dt>Data dokumentu</dt><dd>{dateLabel(modal.expense.date)}</dd></div><div><dt>Koszt podatkowy</dt><dd>{money(modal.expense.deductible)}</dd></div><div><dt>Dowód zakupu</dt><dd>{modal.expense.evidence || "—"}</dd></div></dl>{modal.expense.notes && <p className="inline-note">{modal.expense.notes}</p>}<h4>Załączniki</h4><div className="attachments">{data.attachments.filter(f => f.expenseId === modal.expense?.id).map(f => <a key={f.id} href={`/api/files?id=${f.id}`}><Paperclip size={16} />{f.name}<Download size={15} /></a>)}</div><label className="upload-box"><Upload size={21} /><span>Dodaj dowód PDF, JPG lub PNG (do 5 MB)</span><input type="file" accept="application/pdf,image/jpeg,image/png" disabled={saving || !user} onChange={async e => { const file = e.target.files?.[0]; if (!file) return; setSaving(true); try { const fd = new FormData(); fd.set("file", file); fd.set("expenseId", modal.expense!.id); const r = await fetch("/api/files", { method: "POST", body: fd }); const b: any = await r.json(); if (!r.ok) throw new Error(b.error); await refresh(); notify("Dowód zakupu zapisany."); } catch (e) { setFormError((e as Error).message); } finally { setSaving(false); } }} /></label>{formError && <p className="form-error">{formError}</p>}<p className="inline-note">Wydatek korygujesz nowym wpisem z odpowiednim znakiem i odniesieniem do tego dowodu. Historia pozostaje zachowana.</p></div>}
      {modal.type === "export" && <div className="detail-body"><p className="muted">Eksport tabel dotyczy okresu: {periodName}. Kopia JSON obejmuje wszystkie lata.</p><div className="export-list">{[["sales", "Ewidencja sprzedaży", "Przychód należny i dokumenty"], ["payments", "Otrzymane wpłaty", "Przychody kasowe do PIT"], ["expenses", "Wydatki i koszty", "Dowody, daty i kwoty"], ["clients", "Baza klientów", "Kontakty i notatki"]].map(([id, label, text]) => <button key={id} onClick={() => exportCsv(id)}><span className="export-icon"><FileText size={20} /></span><span><strong>{label}</strong><small>{text} · CSV / Excel</small></span><Download size={17} /></button>)}</div><div className="backup-actions"><button className="btn primary" onClick={backup}><Download size={16} />Pełna kopia JSON</button><button className="btn ghost" disabled={saving || !user} onClick={() => importRef.current?.click()}><Upload size={16} />Import kopii</button></div><p className="inline-note">Import dopisuje kontakty, sprzedaże, płatności i wydatki w partiach, bez nadpisywania istniejących. Profil i prognozę PIT odtwarzasz z kopii ręcznie. Pliki załączników pobieraj osobno.</p><div className="detail-actions"><button className="btn ghost" onClick={() => print("sales")}><Printer size={16} />Drukuj ewidencję</button><button className="btn ghost" onClick={() => print("tax")}><Printer size={16} />Roczny raport PIT</button></div></div>}
    </div></div>}

    <section className="print-only"><div className="print-header"><div><BookOpen size={30} /><h1>Mała Księga</h1></div><p>{data.settings.sellerName || "Ewidencja działalności nierejestrowanej"}<br />{data.settings.sellerAddress}</p></div>{printMode === "sale" && printSale ? <><h2>Potwierdzenie wpisu {printSale.number}</h2><p>Data wystawienia: {dateLabel(printSale.issueDate)} · Data sprzedaży: {dateLabel(printSale.date)}</p>{(() => { const snap = JSON.parse(printSale.snapshot || "{}"); return <div className="print-parties"><div><h3>Sprzedawca — dane z dnia wpisu</h3><p>{snap.seller?.sellerName || "Nie uzupełniono"}<br />{snap.seller?.sellerAddress}<br />{snap.seller?.sellerNip ? "NIP: " + snap.seller.sellerNip : ""}</p></div><div><h3>Klient — dane z dnia wpisu</h3><p>{snap.client?.name || printSale.clientName}<br />{snap.client?.address}<br />{snap.client?.nip ? "NIP: " + snap.client.nip : ""}</p></div></div>; })()}<table><thead><tr><th>Przedmiot sprzedaży</th><th>Kwota brutto PLN</th></tr></thead><tbody><tr><td>{printSale.description}</td><td>{money(printSale.amount)}</td></tr></tbody></table>{printSale.reason && <p>Powód korekty: {printSale.reason}</p>}<p>Termin płatności: {dateLabel(printSale.dueDate)}.</p><p>Potwierdzenie wpisu w ewidencji. Nie jest paragonem fiskalnym ani potwierdzeniem wysłania do KSeF. Nie zastępuje faktury wymaganej przepisami.</p></> : printMode === "sales" ? <><h2>Ewidencja sprzedaży należnej · {periodName}</h2><table><thead><tr><th>Data</th><th>Numer</th><th>Klient / opis</th><th>Kwota</th></tr></thead><tbody>{[...a.sales].reverse().map(s => <tr key={s.id}><td>{dateLabel(s.date)}</td><td>{s.number}</td><td>{s.clientName}<br />{s.description}</td><td>{money(s.amount)}</td></tr>)}</tbody></table><h3>Suma: {money(a.due)}</h3><p>Suma z zakresu dat nie zastępuje oddzielnej kontroli każdego limitu miesięcznego lub kwartalnego.</p></> : <><h2>Zestawienie do PIT-36 za {year}</h2>{breach && <p><strong>W historii wystąpiło przekroczenie limitu DN {dateLabel(breach)}. Konieczne odrębne rozliczenie JDG od tego dnia.</strong></p>}<table><tbody><tr><td>Przychód faktycznie otrzymany</td><td>{money(tax.received)}</td></tr><tr><td>Udokumentowane, zapłacone koszty podatkowe</td><td>{money(tax.deductible)}</td></tr><tr><td>Dochód</td><td>{money(Math.max(0, tax.profit))}</td></tr><tr><td>Strata</td><td>{money(tax.loss)}</td></tr><tr><td>Inne dochody na skali (wpisane ręcznie)</td><td>{money(tax.input.otherIncome)}</td></tr><tr><td>Odliczenia od dochodu (wpisane ręcznie)</td><td>{money(tax.input.deductions)}</td></tr><tr><td>Orientacyjny łączny podatek po wpisanych ulgach</td><td>{money(tax.tax)}</td></tr><tr><td>Zaliczki / pobrany podatek (wpisane ręcznie)</td><td>{money(tax.input.advances)}</td></tr><tr><td>Orientacyjna dopłata (+) / zwrot (−)</td><td>{money(tax.balance)}</td></tr></tbody></table><p>Termin rozliczenia: {dateLabel(filingDeadline(year))}. Zestawienie jest materiałem pomocniczym do PIT-36, a nie złożonym zeznaniem. Prognoza indywidualna, bez wspólnego rozliczenia, wszystkich ulg i rozliczania dawnych strat.</p><h3>Przychody kasowe</h3><table><thead><tr><th>Data wpływu</th><th>Dokument</th><th>Kwota</th></tr></thead><tbody>{tax.payments.map(p => <tr key={p.id}><td>{dateLabel(p.date)}</td><td>{data.sales.find(s => s.id === p.saleId)?.number}</td><td>{money(p.amount)}</td></tr>)}</tbody></table><h3>Zapłacone koszty</h3><table><thead><tr><th>Data zapłaty</th><th>Dowód / opis</th><th>Koszt podatkowy</th></tr></thead><tbody>{tax.expenses.map(e => <tr key={e.id}><td>{dateLabel(e.paidDate)}</td><td>{e.evidence} — {e.description}</td><td>{money(e.deductible)}</td></tr>)}</tbody></table></>}<p className="print-footer">Wygenerowano {dateLabel(today())}. Reguły podatkowe sprawdzone {dateLabel(CHECKED_DATE)}. https://www.podatki.gov.pl/poradniki-i-informatory/dzialalnosc-nierejestrowana</p></section>
  </>;
}
